import java.util.*;

class Solution {
    public void printOneToN(int n) {
        printFrom(1, n);
    }

    private void printFrom(int current, int n) {
        if (current > n) {
            return;
        }
        if (current > 1) {
            System.out.print(" ");
        }
        System.out.print(current);
        printFrom(current + 1, n);
    }
}
